import pandas as pd
import numpy as np
import json
from scipy import stats as scipy_stats

df = pd.read_csv('/data/df.csv')

result = {
    "eda_summary": {},
    "correlations": {},
    "trends": [],
    "segments": [],
    "anomalies": [],
    "statistical_tests": [],
    "forecast_points": [],
    "distributions": {},
    "head_preview": [],
    "dtypes_summary": {},
    "missing_pct": {},
    "assumptions": [],
}

try:
    carrier_ontime = df.groupby('carrier')['on_time'].mean().reset_index()
    result['segments'].append({
        "segment_column": "carrier",
        "metric_column": "on_time",
        "aggregation": "ratio",
        "label": "on_time_rate",
        "results": [{"name": str(row['carrier']), "value": round(float(row['on_time']), 4)}
                    for _, row in carrier_ontime.iterrows()]
    })
except Exception:
    pass

try:
    dist_ontime = df.groupby('distance_band')['on_time'].mean().reset_index()
    result['segments'].append({
        "segment_column": "distance_band",
        "metric_column": "on_time",
        "aggregation": "ratio",
        "label": "on_time_rate",
        "results": [{"name": str(row['distance_band']), "value": round(float(row['on_time']), 4)}
                    for _, row in dist_ontime.iterrows()]
    })
except Exception:
    pass

try:
    from scipy.stats import chi2_contingency
    ct = pd.crosstab(df['carrier'], df['on_time'])
    chi2, p, dof, expected = chi2_contingency(ct)
    chi2 = float(chi2)
    p = float(p)
    dof = int(dof)
    result['statistical_tests'].append({
        "test_name": "chi-square test of independence: carrier vs on_time",
        "statistic": round(chi2, 4),
        "p_value": round(p, 6),
        "interpretation": (
            f"chi2={chi2:.4f}, p={p:.6g}, dof={dof}. "
            + ("Carrier is significantly associated with on-time delivery." if p < 0.05
               else "No significant relationship between carrier and on-time delivery.")
        )
    })
except Exception:
    pass

try:
    from scipy.stats import chi2_contingency
    ct2 = pd.crosstab(df['distance_band'], df['on_time'])
    chi2b, pb, dofb, _ = chi2_contingency(ct2)
    chi2b = float(chi2b)
    pb = float(pb)
    dofb = int(dofb)
    result['statistical_tests'].append({
        "test_name": "chi-square test of independence: distance_band vs on_time",
        "statistic": round(chi2b, 4),
        "p_value": round(pb, 6),
        "interpretation": (
            f"chi2={chi2b:.4f}, p={pb:.6g}, dof={dofb}. "
            + ("Distance band is significantly associated with on-time delivery." if pb < 0.05
               else "No significant relationship between distance_band and on-time delivery.")
        )
    })
except Exception:
    pass

try:
    from scipy.stats import chi2_contingency
    ct3 = pd.crosstab(df['carrier'], [df['distance_band'], df['on_time']])
    carriers = df['carrier'].unique()
    dist_bands = df['distance_band'].unique()
    stratum_results = []
    for band in dist_bands:
        sub = df[df['distance_band'] == band]
        if sub['carrier'].nunique() < 2:
            continue
        ct_s = pd.crosstab(sub['carrier'], sub['on_time'])
        if ct_s.shape[0] < 2 or ct_s.shape[1] < 2:
            continue
        chi2s, ps, dofs, _ = chi2_contingency(ct_s)
        chi2s = float(chi2s)
        ps = float(ps)
        dofs = int(dofs)
        stratum_results.append({
            "test_name": f"chi-square: carrier vs on_time within distance_band={band}",
            "statistic": round(chi2s, 4),
            "p_value": round(ps, 6),
            "interpretation": (
                f"chi2={chi2s:.4f}, p={ps:.6g}, dof={dofs}. "
                + ("Carrier significantly associated with on-time within this band." if ps < 0.05
                   else "No significant relationship between carrier and on-time delivery.")
            )
        })
    result['statistical_tests'].extend(stratum_results)
except Exception:
    pass

try:
    joint = df.groupby(['carrier', 'distance_band'])['on_time'].mean().reset_index()
    result['segments'].append({
        "segment_column": "carrier|distance_band",
        "metric_column": "on_time",
        "aggregation": "ratio",
        "label": "on_time_rate",
        "results": [
            {"name": f"{row['carrier']}|{row['distance_band']}", "value": round(float(row['on_time']), 4)}
            for _, row in joint.iterrows()
        ]
    })
except Exception:
    pass

result['assumptions'].append("on_time treated as binary flag; rate = mean(on_time) per group.")
result['assumptions'].append("Chi-square used for carrier vs on_time (categorical vs binary).")
result['assumptions'].append("Stratum tests check for Simpson's paradox across distance_band.")

