from scipy import stats as scipy_stats

df = pd.read_csv('/data/df.csv')

result = {
    "eda_summary": {},
    "correlations": {},
    "trends": [],
    "segments": [],
    "anomalies": [],
    "statistical_tests": [],
    "forecast_points": [],
    "distributions": {},
    "head_preview": [],
    "dtypes_summary": {},
    "missing_pct": {},
    "assumptions": [],
}

try:
    sale_df = df[df['row_kind'] == 'sale'].copy()

    for col in ['Delivered Date', 'Requested Date', 'Order Date']:
        sale_df[col] = pd.to_datetime(sale_df[col], errors='coerce')

    last_order_date = sale_df['Order Date'].max()

    late_statuses = [
        'in transit', 'out for delivery', 'picked up', 'exception', 'delivery exception',
        'delayed', 'tendered', 'booked', 'dispatched', 'pending', 'shipped',
        'partially shipped', 'backordered', 'short shipped', 'open', 'allocated',
        'released', 'picked', 'packed'
    ]
    sale_df['_status_lower'] = sale_df['Status'].str.lower().str.strip()

    def compute_otif_orders(sub):
        delivered_mask = sub['_status_lower'] == 'delivered'
        open_mask = (sub['_status_lower'].isin(late_statuses)) & (sub['days_past_due'] > 0)
        judged_mask = delivered_mask | open_mask

        judged = sub[judged_mask].copy()
        if judged.empty:
            return float('nan'), 0

        judged_orders = judged.groupby('Order ID')

        def order_is_otif(grp):
            all_lines_otif = (
                (grp['days_before_promise'] >= 0) &
                (grp['shipped_minus_ordered'] >= 0)
            ).all()
            return all_lines_otif

        order_otif = judged_orders.apply(order_is_otif)
        n_otif = order_otif.sum()
        n_total = order_otif.count()
        return (n_otif / n_total) if n_total > 0 else float('nan'), int(n_total)

    warehouses = sale_df['Warehouse'].dropna().unique()
    wh_results = []
    for wh in sorted(warehouses):
        sub = sale_df[sale_df['Warehouse'] == wh]
        rate, n = compute_otif_orders(sub)
        wh_results.append({"name": str(wh), "value": round(float(rate), 6) if not (rate != rate) else float('nan')})

    overall_rate, overall_n = compute_otif_orders(sale_df)

    result['segments'].append({
        "segment_column": "Warehouse",
        "metric_column": "Order ID",
        "aggregation": "ratio",
        "label": "otif_order",
        "results": wh_results
    })

    result['assumptions'].append(
        f"OTIF (order): judged lines = delivered + open lines past due as of last order date ({last_order_date.date()}); "
        f"order is OTIF only if every judged line is on-time AND shipped in full; "
        f"overall OTIF order rate = {overall_rate:.4f} over {overall_n} orders."
    )
    result['assumptions'].append(
        "Only row_kind='sale' rows included; cancelled and other-currency rows excluded."
    )
    result['assumptions'].append(
        "days_before_promise, days_past_due, shipped_minus_ordered used as provided; not recomputed."
    )

except Exception as e:
    result['segments'].append({
        "segment_column": "Warehouse",
        "metric_column": "Order ID",
        "aggregation": "ratio",
        "label": "otif_order",
        "results": [{"name": "error", "value": float('nan')}]
    })
    result['assumptions'].append(f"OTIF order segmentation failed: {str(e)}")

