            (sub['days_before_promise'] >= 0) | (sub['days_late'] > 0)
        )]
        judged_open = sub[open_mask & (sub['days_past_due'] > 0)]

        judged = pd.concat([judged_delivered, judged_open]).drop_duplicates()

        eligible_orders = judged.groupby('Order ID').size().reset_index()[['Order ID']]

        if len(eligible_orders) == 0:
            return 0.0, 0

        failed_delivered = judged_delivered[
            (judged_delivered['days_late'] > 0) |
            (judged_delivered['shipped_minus_ordered'] < 0)
        ]
        failed_open = judged_open.copy()
        failed_lines = pd.concat([failed_delivered, failed_open]).drop_duplicates()
        failed_orders = set(failed_lines['Order ID'].unique())

        eligible_order_ids = set(eligible_orders['Order ID'].unique())
        otif_order_ids = eligible_order_ids - failed_orders

        n_eligible = len(eligible_order_ids)
        n_otif = len(otif_order_ids)
        rate = n_otif / n_eligible if n_eligible > 0 else 0.0
        return rate, n_eligible

    warehouses = sale_df['Warehouse'].dropna().unique()
    wh_results = []
    for wh in warehouses:
        sub = sale_df[sale_df['Warehouse'] == wh]
        rate, n_elig = compute_otif_orders(sub)
        wh_results.append({"name": str(wh), "value": round(float(rate), 6)})

    wh_results_sorted = sorted(wh_results, key=lambda x: x['value'], reverse=True)

    overall_rate, overall_elig = compute_otif_orders(sale_df)

    result['segments'].append({
        "segment_column": "Warehouse",
        "metric_column": "Order ID",
        "aggregation": "ratio",
        "label": "otif_order",
        "results": wh_results_sorted
    })

    result['segments'].append({
        "segment_column": "Warehouse",
        "metric_column": "Order ID",
        "aggregation": "ratio",
        "label": "otif_order_overall",
        "results": [{"name": "Overall", "value": round(float(overall_rate), 6)}]
    })

    result['assumptions'].append(
        "OTIF (order): eligible = orders with at least one line delivered (on-time or late) or open past due; "
        "failed = orders with any late delivery or undership or open-past-due line; rate = OTIF orders / eligible orders."
    )
    result['assumptions'].append(
        f"Last order date used as cutoff for open-past-due: {last_order_date}"
    )
    result['assumptions'].append(
        "Only row_kind='sale' rows included; cancelled and other-currency rows excluded."
    )

except Exception as e:
    result['segments'].append({
        "segment_column": "Warehouse",
        "metric_column": "Order ID",
        "aggregation": "ratio",
        "label": "otif_order_error",
        "results": [{"name": "error", "value": 0.0}]
