}

try:
    sale_mask = df['row_kind'] == 'sale'
    usd_mask = df['Currency'] == 'USD'
    base = df[sale_mask & usd_mask].copy()

    weight_mask = (base['Weight'] > 0) & (base['Weight UOM'].notna())
    cost_per_lb_base = base[weight_mask]

    mode_groups = cost_per_lb_base.groupby('Mode')
    cpl_results = []
    for mode_val, grp in mode_groups:
        total_cost = grp['Total Charge'].sum()
        total_weight = grp['Weight'].sum()
        cpl = total_cost / total_weight if total_weight > 0 else float('nan')
        cpl_results.append({"name": str(mode_val), "value": round(float(cpl), 6)})

    result['segments'].append({
        "segment_column": "Mode",
        "metric_column": "Total Charge",
        "aggregation": "ratio",
        "label": "cost_per_lb",
        "results": sorted(cpl_results, key=lambda x: x['value'], reverse=True)
    })

    tc_by_mode = base.groupby('Mode')['Total Charge'].sum().reset_index()
    tc_by_mode = tc_by_mode.sort_values('Total Charge', ascending=False).head(10)
    result['segments'].append({
        "segment_column": "Mode",
        "metric_column": "Total Charge",
        "aggregation": "sum",
        "label": None,
        "results": [{"name": str(r['Mode']), "value": round(float(r['Total Charge']), 6)} for _, r in tc_by_mode.iterrows()]
    })

    w_by_mode = base[weight_mask].groupby('Mode')['Weight'].sum().reset_index()
    w_by_mode = w_by_mode.sort_values('Weight', ascending=False).head(10)
    result['segments'].append({
        "segment_column": "Mode",
        "metric_column": "Weight",
        "aggregation": "sum",
        "label": None,
        "results": [{"name": str(r['Mode']), "value": round(float(r['Weight']), 6)} for _, r in w_by_mode.iterrows()]
    })

    uom_by_mode = base.groupby('Mode')['Weight UOM'].agg(lambda x: x.mode()[0] if len(x) > 0 else None).reset_index()
    result['segments'].append({
        "segment_column": "Mode",
        "metric_column": "Weight UOM",
        "aggregation": "count",
        "label": "dominant_uom",
        "results": [{"name": str(r['Mode']), "value": float(base[(base['Mode'] == r['Mode']) & (base['Weight UOM'] == r['Weight UOM'])].shape[0])} for _, r in uom_by_mode.iterrows()]
    })

    result['assumptions'].append("cost_per_lb = sum(Total Charge) / sum(Weight) for sale+USD rows with Weight > 0 and Weight UOM present")
    result['assumptions'].append("889 rows had kg weights converted to LB before analysis; 5 rows with unknown UOM excluded from cost_per_lb")
    result['assumptions'].append("73 cancelled and 87 non-USD rows excluded from all figures")

except Exception as e:
