    df_sale = df[sale_mask].copy()

    # avg_transit_days by Mode: sum of transit_days (>=0) / count of distinct shipments with transit_days >= 0
    valid_transit = df_sale[df_sale['transit_days'] >= 0].copy()

    mode_groups = valid_transit.groupby('Mode')

    mode_results = []
    for mode_val, grp in mode_groups:
        total_days = grp['transit_days'].sum()
        distinct_shipments = grp['Shipment ID'].nunique()
        avg_transit = total_days / distinct_shipments if distinct_shipments > 0 else float('nan')
        mode_results.append({"name": str(mode_val), "value": round(float(avg_transit), 4)})

    mode_results_sorted = sorted(mode_results, key=lambda x: x['value'], reverse=True)

    result['segments'].append({
        "segment_column": "Mode",
        "metric_column": "transit_days",
        "aggregation": "ratio",
        "label": "avg_transit_days",
        "results": mode_results_sorted
    })

    result['assumptions'].append("avg_transit_days = sum(transit_days) / count(distinct shipments) where transit_days >= 0, sale rows, USD only.")
