import pandas as pd
import numpy as np
import json
from scipy import stats as scipy_stats

df = pd.read_csv('/data/df.csv')

result = {
    "eda_summary": {},
    "correlations": {},
    "trends": [],
    "segments": [],
    "anomalies": [],
    "statistical_tests": [],
    "forecast_points": [],
    "distributions": {},
    "head_preview": [],
    "dtypes_summary": {},
    "missing_pct": {},
    "assumptions": [],
}

try:
    sale_mask = (df['row_kind'] == 'sale') & (df['Currency'] == 'USD')
    dfs = df[sale_mask].copy()

    last_ship_date = dfs['Ship Date'].max()

    def is_on_time(row):
        if row['Status'] in ['Delivered', 'delivered']:
            return 1 if row['days_before_promise'] >= 0 else 0
        elif row['Status'] in ['Returned to Sender', 'returned_to_sender']:
            return 0
        else:
            if row['days_past_due'] > 0:
                return 0
            return None

    dfs['_on_time'] = dfs.apply(is_on_time, axis=1)

    seg_col = 'Mode'
    metric_col = 'transit_days'

    valid_transit = dfs[dfs[metric_col] >= 0]

    mode_transit = (
        valid_transit.groupby(seg_col)[metric_col]
        .apply(lambda x: x.sum() / x.count())
        .reset_index()
    )
    mode_transit.columns = [seg_col, 'avg_transit_days']

    transit_results = [
        {"name": str(row[seg_col]), "value": round(float(row['avg_transit_days']), 4)}
        for _, row in mode_transit.iterrows()
    ]

    result['segments'].append({
        "segment_column": seg_col,
        "metric_column": metric_col,
        "aggregation": "mean",
        "label": "avg_transit_days",
        "results": transit_results
    })

    ot_denom = dfs[dfs['_on_time'].notna()]
    mode_ot = ot_denom.groupby(seg_col).apply(
        lambda g: g['_on_time'].sum() / g['_on_time'].count() if g['_on_time'].count() > 0 else float('nan')
    ).reset_index()
    mode_ot.columns = [seg_col, 'on_time_rate']

    ot_results = [
        {"name": str(row[seg_col]), "value": round(float(row['on_time_rate']), 4)}
        for _, row in mode_ot.iterrows()
        if not (row['on_time_rate'] != row['on_time_rate'])
    ]

    result['segments'].append({
        "segment_column": seg_col,
        "metric_column": "days_before_promise",
        "aggregation": "ratio",
        "label": "on_time_rate",
        "results": ot_results
    })

    mode_count = dfs.groupby(seg_col).size().reset_index(name='shipment_count')
    count_results = [
        {"name": str(row[seg_col]), "value": float(row['shipment_count'])}
        for _, row in mode_count.iterrows()
    ]

    result['segments'].append({
        "segment_column": seg_col,
        "metric_column": "Shipment ID",
        "aggregation": "count",
        "label": "shipment_count",
        "results": count_results
    })

    result['assumptions'].append("avg_transit_days = sum(transit_days) / count where transit_days >= 0, sale+USD rows only")
    result['assumptions'].append("on_time_rate = delivered on/before promised date; open past-due rows counted as late")
    result['assumptions'].append("transit_days column used as provided; not recomputed")

except Exception as e:
    result['assumptions'].append(f"segmentation error: {str(e)}")

